const { withAppBuildGradle } = require('@expo/config-plugins');

// A GGUF model ships bundled inside the APK (android/app/src/main/assets/models/,
// placed by scripts/fetch-bundled-model.sh) so the app is preloaded with an
// on-device LLM — no download needed. The file is already compressed, so store
// it uncompressed: it keeps the APK from ballooning and lets the app copy it out
// of assets quickly on first launch. android/ is regenerated by prebuild, so we
// re-apply this `noCompress` rule as a config plugin for persistence.
module.exports = function withBundledModel(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') return cfg;
    let src = cfg.modResults.contents;
    if (src.includes("noCompress 'gguf'")) return cfg;

    // Prefer the androidResources block (AGP 8+); fall back to aaptOptions.
    if (/androidResources\s*\{/.test(src)) {
      src = src.replace(
        /androidResources\s*\{/,
        "androidResources {\n        noCompress 'gguf'"
      );
    } else {
      // Insert an androidResources block just inside the `android {` block.
      src = src.replace(
        /\nandroid\s*\{/,
        "\nandroid {\n    androidResources {\n        noCompress 'gguf'\n    }"
      );
    }

    cfg.modResults.contents = src;
    return cfg;
  });
};
